/* =========================================================
   img-data.js — 画布生成用的内嵌图片（data URL）
   避免 file:// 下 Canvas 因跨源图片被判为 tainted
   ========================================================= */
(function () {
  window.BANNER_IMG = {
    headphone: 'data:image/jpeg;base64,',
    product: 'data:image/jpeg;base64,',
    interiorA: 'data:image/jpeg;base64,',
    interiorB: 'data:image/jpeg;base64,'
  };
})();

/* ---- 三个提示词模版的参考图（用于图生图与合成） ---- */
(function () {
  var b = window.BANNER_IMG;
  b.tpl_misirui = 'data:image/jpeg;base64,';
  b.tpl_colorx = 'data:image/jpeg;base64,';
  b.tpl_creality = 'data:image/jpeg;base64,';
})();

